// Tag filter of docs/book/tutorials/index.md (generated by generate_tutorial_index.py).
// The panel holds one chip per tag that occurs (.zt-chip[data-tag="category:value"]); the field
// above the grid holds the selected tags as pills plus a text input with autocomplete.  Both edit
// one list, `sel`.  A card (its .zt-data span carries data-tags, copied onto the grid column) is
// shown when it carries ALL selected tags; each chip's count is the number of cards that would
// remain if it were added.  The selection lives in the URL hash, one cat=value pair per tag
// (#physics=hydrostatic&physics=viscous&dimension=1d), so the back button from a notebook
// returns to the same view.
document.addEventListener("DOMContentLoaded", function () {
  var root = document.querySelector(".zt-layout");
  if (!root || root.dataset.ztInit) return;   // jupyter-book lists the script twice: run once
  root.dataset.ztInit = "1";
  var pillBox = root.querySelector(".zt-pills"), input = root.querySelector(".zt-text");
  var list = root.querySelector(".zt-suggest"), status = root.querySelector(".zt-status");
  var empty = root.querySelector(".zt-empty");
  var tags = [], byTag = {}, cards = [], sel = [], found = [], active = -1;

  root.querySelectorAll(".zt-chip").forEach(function (chip) {
    var tag = chip.dataset.tag, parts = tag.split(":");
    var t = { tag: tag, cat: parts[0], value: parts[1], chip: chip, n: 0,
              hue: chip.closest(".zt-group").style.getPropertyValue("--zt-h"),
              badge: chip.querySelector(".zt-n") };
    tags.push(t);
    byTag[tag] = t;
    chip.addEventListener("click", function () { toggle(tag); });
  });
  document.querySelectorAll(".zt-data").forEach(function (span) {
    var col = span.closest(".sd-col") || span.closest(".sd-card");
    cards.push({ col: col, tags: span.dataset.tags.split(" ") });
  });

  function toggle(tag) {
    var i = sel.indexOf(tag);
    if (i >= 0) sel.splice(i, 1); else sel.push(tag);
    render();
  }

  function render() {
    var shown = cards.filter(function (c) {
      return sel.every(function (t) { return c.tags.indexOf(t) >= 0; });
    });
    cards.forEach(function (c) { c.col.hidden = shown.indexOf(c) < 0; });
    tags.forEach(function (t) {
      var on = sel.indexOf(t.tag) >= 0;
      t.n = on ? shown.length : shown.filter(function (c) { return c.tags.indexOf(t.tag) >= 0; }).length;
      t.badge.textContent = t.n;
      t.chip.classList.toggle("zt-on", on);
      t.chip.setAttribute("aria-pressed", on);
      t.chip.disabled = !on && t.n === 0;
    });
    pillBox.textContent = "";
    sel.forEach(function (tag) {
      var t = byTag[tag], pill = document.createElement("span"), x = document.createElement("button");
      pill.className = "zt-pill";
      pill.style.setProperty("--zt-h", t.hue);
      pill.title = t.cat + ": " + t.value;
      pill.appendChild(document.createTextNode(t.value));
      x.type = "button";
      x.textContent = "×";
      x.setAttribute("aria-label", "remove " + tag);
      x.addEventListener("mousedown", function (e) { e.preventDefault(); });   // keep the field focused
      x.addEventListener("click", function () { toggle(tag); input.focus(); });
      pill.appendChild(x);
      pillBox.appendChild(pill);
    });
    if (empty) empty.hidden = shown.length > 0 || cards.length === 0;
    status.textContent = shown.length + " of " + cards.length + " notebooks";
    var hash = sel.map(function (tag) {
      return byTag[tag].cat + "=" + encodeURIComponent(byTag[tag].value);
    }).join("&");
    history.replaceState(null, "", location.pathname + location.search + (hash ? "#" + hash : ""));
    suggest();
  }

  // Tags matching what was typed, best first: rank 0 exact value, 1 value prefix, 2 value
  // substring, 3 category prefix.  "cat:val" restricts to categories starting with cat.
  function match(q) {
    q = q.trim().toLowerCase();
    var cat = "", i = q.indexOf(":");
    if (i >= 0) { cat = q.slice(0, i); q = q.slice(i + 1); }
    var out = [];
    if (!q && !cat) return out;
    tags.forEach(function (t) {
      if (cat && t.cat.indexOf(cat) !== 0) return;
      var at = t.value.indexOf(q);
      var rank = t.value === q ? 0 : at === 0 ? 1 : at > 0 ? 2 : (!cat && t.cat.indexOf(q) === 0) ? 3 : -1;
      if (rank >= 0) out.push({ t: t, rank: rank });
    });
    return out.sort(function (a, b) { return a.rank - b.rank; });
  }

  // The one tag a typed token means, or null: the single best-ranked tag by value (exact, then
  // prefix, then substring); a tie, or a category-only match, is ambiguous.
  function resolve(token) {
    var hits = match(token).filter(function (h) { return h.rank < 3; });
    if (!hits.length) return null;
    var best = hits.filter(function (h) { return h.rank === hits[0].rank; });
    return best.length === 1 ? best[0].t : null;
  }

  function lastToken() { return input.value.slice(input.value.lastIndexOf(",") + 1); }

  function suggest() {
    list.textContent = "";
    active = -1;
    input.removeAttribute("aria-activedescendant");
    found = match(lastToken()).map(function (h) { return h.t; }).filter(function (t) {
      return sel.indexOf(t.tag) < 0;
    }).slice(0, 10);
    found.forEach(function (t, i) {
      var li = document.createElement("li"), b = document.createElement("b"), n = document.createElement("span");
      li.className = "zt-opt" + (t.n ? "" : " zt-zero");
      li.id = "zt-opt-" + i;
      li.setAttribute("role", "option");
      li.style.setProperty("--zt-h", t.hue);
      li.title = t.cat + ": " + t.value;
      li.innerHTML = '<span class="zt-dot"></span>';
      b.textContent = t.value;
      n.className = "zt-n";
      n.textContent = t.n;
      li.appendChild(document.createTextNode(t.cat + ":"));
      li.appendChild(b);
      li.appendChild(n);
      li.addEventListener("mousedown", function (e) { e.preventDefault(); accept(t); });
      list.appendChild(li);
    });
    list.hidden = !found.length || document.activeElement !== input;
    input.setAttribute("aria-expanded", !list.hidden);
  }

  function accept(t) {
    input.value = input.value.slice(0, input.value.lastIndexOf(",") + 1).trim();
    input.classList.remove("zt-bad");
    if (sel.indexOf(t.tag) < 0) sel.push(t.tag);
    render();
  }

  // Commit the complete tokens of the field (all of them when `all`); a token that does not
  // resolve stays in the field and the field is marked.
  function commit(all) {
    var parts = input.value.split(","), rest = all ? "" : parts.pop(), keep = [], n = sel.length;
    parts.forEach(function (p) {
      if (!p.trim()) return;
      var t = resolve(p);
      if (!t) keep.push(p.trim());
      else if (sel.indexOf(t.tag) < 0) sel.push(t.tag);
    });
    input.value = keep.concat(all ? [] : [rest.replace(/^\s+/, "")]).join(", ");
    input.classList.toggle("zt-bad", keep.length > 0);
    if (sel.length !== n) render(); else suggest();
  }

  function mark(i) {
    var items = list.children;
    if (active >= 0) items[active].classList.remove("zt-act");
    active = (i + items.length) % items.length;
    items[active].classList.add("zt-act");
    items[active].scrollIntoView({ block: "nearest" });
    input.setAttribute("aria-activedescendant", items[active].id);
  }

  input.addEventListener("input", function () {
    input.classList.remove("zt-bad");
    if (input.value.indexOf(",") >= 0) commit(false); else suggest();
  });
  input.addEventListener("focus", suggest);
  input.addEventListener("blur", function () { commit(true); list.hidden = true; });
  input.addEventListener("keydown", function (e) {
    var open = !list.hidden, token = lastToken().trim(), pick = null;
    if (e.key === "ArrowDown" && open) { e.preventDefault(); mark(active + 1); }
    else if (e.key === "ArrowUp" && open) { e.preventDefault(); mark(active - 1); }
    else if (e.key === "Escape") { list.hidden = true; }
    else if (e.key === "Backspace" && !input.value && sel.length) { sel.pop(); render(); }
    else if (e.key === "Enter" || (e.key === "Tab" && open && token && !e.shiftKey)) {
      if (open && active >= 0) pick = found[active];
      else if (token) pick = resolve(token) || (e.key === "Tab" ? found[0] : null);
      if (e.key === "Enter" || pick) e.preventDefault();
      if (pick) accept(pick);
      else if (token && e.key === "Enter") input.classList.add("zt-bad");
    }
  });
  root.querySelector(".zt-clear").addEventListener("click", function () {
    sel = [];
    input.value = "";
    input.classList.remove("zt-bad");
    render();
  });
  document.addEventListener("click", function (e) { if (!e.target.closest(".zt-box")) list.hidden = true; });

  function fromHash() {
    sel = [];
    location.hash.replace(/^#/, "").split("&").forEach(function (pair) {
      var kv = pair.split("="), tag = kv[0] + ":" + (kv[1] || "").replace(/%([0-9a-f]{2})/gi, function (m, h) {
        return String.fromCharCode(parseInt(h, 16));
      });
      if (byTag[tag] && sel.indexOf(tag) < 0) sel.push(tag);
    });
    render();
  }
  window.addEventListener("hashchange", fromHash);
  root.classList.add("zt-ready");
  fromHash();
});
